import{c as t,Q as o,j as r,m as a}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"Low Budget Hosts or Low Settings Servers","description":"","frontmatter":{},"headers":[],"relativePath":"general/low-budget-hosts.md","filePath":"general/low-budget-hosts.md"}'),s={name:"general/low-budget-hosts.md"};function i(n,e,l,d,h,m){return o(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="low-budget-hosts-or-low-settings-servers" tabindex="-1">Low Budget Hosts or Low Settings Servers <a class="header-anchor" href="#low-budget-hosts-or-low-settings-servers" aria-label="Permalink to &quot;Low Budget Hosts or Low Settings Servers&quot;">​</a></h1><p>On some hosts like <strong>GoDaddy, 1&amp;1 and Hostgator</strong> basic plans, you may experience issues such as demo content import failure, endless loading, incomplete page rendering, etc. All these problems are caused by the fact that the base plans of these hosts do not meet the minimum <a href="./server-requirements.html">Server Requirements</a> to work with modern WordPress themes. For example, the memory limit of these hosts is too low (approximately 40MB), while the <a href="http://codex.wordpress.org/Editing_wp-config.php#Increasing_memory_allocated_to_PHP" target="_blank" rel="noreferrer">official WordPress documentation</a> suggests at least 96MB.</p><blockquote><p><strong>We are sorry for the inconvenience but this is out of the scope of our support and something that is isolated to a low-performance host.</strong></p></blockquote><h2 id="how-to-increase-the-limits" tabindex="-1">How to Increase the Limits <a class="header-anchor" href="#how-to-increase-the-limits" aria-label="Permalink to &quot;How to Increase the Limits&quot;">​</a></h2><p>Most problems are caused by the WP Memory Limit — the maximum amount of RAM your site can use at one time. When you reach your memory limit you will encounter a fatal error. WordPress itself, your theme and your plugins all consume memory. The more content and features you add, the higher your memory limit needs to be.</p><p>To increase PHP parameters on GoDaddy, create a new file named <code>php.ini</code> (or edit it if it already exists) and add the following:</p><pre><code>upload_max_filesize = 48M
post_max_size = 48M
memory_limit = 128M
max_execution_time = 600
max_input_vars = 10000
max_input_time = 400
</code></pre><p>Wait a few minutes for the changes to take effect. Note that if your hosting plan does not permit increasing these values, the modifications will not take effect — in that case contact GoDaddy directly to request an increase to the PHP memory limit.</p><ul><li><a href="http://codingcyber.com/how-to-increase-php-memory-limit-on-godaddy-hosting-882/" target="_blank" rel="noreferrer">Follow this tutorial for GoDaddy</a></li></ul><h2 id="consideration" tabindex="-1">Consideration <a class="header-anchor" href="#consideration" aria-label="Permalink to &quot;Consideration&quot;">​</a></h2><p>GoDaddy&#39;s support team may try to up-sell you to a higher plan rather than help you configure your current one. Keep in mind that you get what you pay for — a $0.99/month hosting plan will struggle to run a WordPress site with a modern theme and plugins. For reference, the GoDaddy Ultimate Plan at around $7.49/month can handle approximately one fully-featured WordPress site. Adding more sites will require purchasing more resources.</p><hr><p>To avoid server-side headaches, check our list of <a href="./recommended-web-hosts.html">Recommended Web Hosts</a>.</p>`,13)])])}const p=t(s,[["render",i]]);export{u as __pageData,p as default};
